if (!FUZZ_GET_ATTR_INT(ctx, "is_encoder")) { FUZZ_BAIL(); }

// Encode to internal buffer
int rc = spng_set_option(ctx, (enum spng_option)12 /* SPNG_ENCODE_TO_BUFFER */, 1);
if (rc != 0) { FUZZ_BAIL(); }

// IHDR for RGBA8
struct spng_ihdr ihdr; ihdr.width=(uint32_t)((*FUZZ_PARAM(unsigned int)%32u)+1u); ihdr.height=(uint32_t)((*FUZZ_PARAM(unsigned int)%32u)+1u);
ihdr.bit_depth=8; ihdr.color_type=6; ihdr.compression_method=0; ihdr.filter_method=0; ihdr.interlace_method=(uint8_t)(*FUZZ_PARAM(unsigned int)%2u);
rc = spng_set_ihdr(ctx, &ihdr);
if (rc != 0) { FUZZ_BAIL(); }

// Progressive initialization
int fmt = 1; /* SPNG_FMT_RGBA8 */
rc = spng_encode_image(ctx, nullptr, 0, fmt, 1 /* SPNG_ENCODE_PROGRESSIVE */);
if (rc != 0) { FUZZ_BAIL(); }

// Prepare a row buffer (same size as scanline for RGBA8, but API distinguishes deinterlaced row)
size_t row_len = (size_t)ihdr.width * 4u;
std::string row = FUZZ_PARAM_STR();
if (row.size() < row_len) row.resize(row_len, '\0'); else row.resize(row_len);

rc = spng_encode_row(ctx, (const void*)row.data(), row.size());
if (rc != 0) { FUZZ_BAIL(); }

// Return ctx unchanged

// Require encoder context
if (!FUZZ_GET_ATTR_INT(ctx, "is_encoder")) { FUZZ_BAIL(); }

// Encode to internal buffer
int rc = spng_set_option(ctx, (enum spng_option)12 /* SPNG_ENCODE_TO_BUFFER */, 1);
if (rc != 0) { FUZZ_BAIL(); }

// Minimal IHDR and progressive init to ensure state machine is ready
struct spng_ihdr ihdr; ihdr.width=8; ihdr.height=8; ihdr.bit_depth=8; ihdr.color_type=6; ihdr.compression_method=0; ihdr.filter_method=0; ihdr.interlace_method=0;
