int rc = spng_set_png_buffer(ctx, png.data(), png.size());
if (rc != 0) { FUZZ_BAIL(); }

struct spng_ihdr ihdr;
rc = spng_get_ihdr(ctx, &ihdr);
if (rc != 0) { FUZZ_BAIL(); }
// Basic sanity: dimensions should be >0 on success
FUZZ_ASSERT(ihdr.width > 0 && ihdr.height > 0, "IHDR dimensions must be positive");
