import random
from typing import List, Tuple

# Generator for valid raw RGBA8 pixel bytes.
# Context from fuzz stubs:
# - IHDR is configured to 8-bit RGBA (color_type=6, bit_depth=8)
# - Width/height are in [1..32]
# - For full-image encode, need width*height*4 bytes
# - For progressive scanline/row, need width*4 bytes
# Our output buffer is fed into FUZZ_PARAM_STR() used as the source image/scanline/row.
# Therefore we produce plausible, valid RGBA8 buffers of varying sizes matching
# likely requested lengths. We keep size <= 4096.

MAX_BYTES = 4096

# Some small palettes and patterns to create interesting, but valid images
PALETTES: List[List[Tuple[int,int,int,int]]] = [
    # Basic opaque colors
    [(0,0,0,255), (255,255,255,255), (255,0,0,255), (0,255,0,255), (0,0,255,255)],
    # With alpha variety
    [(0,0,0,0), (255,255,255,128), (255,0,0,64), (0,255,0,200), (0,0,255,255)],
    # Grayscale ramp opaque
    [(i,i,i,255) for i in (0,51,102,153,204,255)],
    # Grayscale ramp with alpha gradient
    [(i,i,i,a) for i,a in zip((0,32,64,96,128,160,192,224,255), (255,224,192,160,128,96,64,32,0))],
]

# Dither-like Bayer 4x4 matrix for alpha masks
_BAYER4 = [
    [0, 8, 2,10],
    [12,4,14, 6],
    [3,11, 1, 9],
    [15,7,13, 5],
]

def _pattern_solid(w: int, h: int, color: Tuple[int,int,int,int]) -> bytes:
    r,g,b,a = color
    row = bytes((r,g,b,a)) * w
    return row * h

def _pattern_checker(w: int, h: int, c0: Tuple[int,int,int,int], c1: Tuple[int,int,int,int], tile: int) -> bytes:
    out = bytearray()
    for y in range(h):
        for x in range(w):
            use0 = ((x//tile) + (y//tile)) & 1 == 0
            r,g,b,a = c0 if use0 else c1
            out += bytes((r,g,b,a))
    return bytes(out)

def _pattern_horizontal_gradient(w: int, h: int, alpha: int) -> bytes:
    out = bytearray()
    for y in range(h):
        for x in range(w):
            t = x/(w-1) if w>1 else 0.0
            r = int(255*t)
            g = int(255*(1.0-t))
            b = int(255*(0.5*(1.0-abs(0.5-t)*2)))
            out += bytes((r,g,b,alpha))
    return bytes(out)

def _pattern_alpha_bayer(w: int, h: int, base: Tuple[int,int,int], strength: int) -> bytes:
    br,bg,bb = base
    out = bytearray()
    for y in range(h):
        for x in range(w):
            a = int(255 * ( (_BAYER4[y%4][x%4] + 1) / 17.0 ))
            a = max(0, min(255, int(a * (strength/255))))
            out += bytes((br,bg,bb,a))
    return bytes(out)

def _pattern_stripes(w: int, h: int, horiz: bool, colors: List[Tuple[int,int,int,int]], stripe: int) -> bytes:
    out = bytearray()
    n = len(colors)
    for y in range(h):
        for x in range(w):
            idx = (y//stripe)%n if horiz else (x//stripe)%n
            r,g,b,a = colors[idx]
            out += bytes((r,g,b,a))
    return bytes(out)

# Choose a width, height combination that keeps size <= MAX_BYTES and matches the fuzzers' 1..32 range.
# Also sometimes generate a single-scanline buffer to satisfy scanline/row stubs.

def _choose_dims(rng: random.Random) -> Tuple[int,int, bool]:
    # decide between full image and single scanline
    single_scan = rng.random() < 0.4
    w = rng.randint(1, 32)
    h = 1 if single_scan else rng.randint(1, 32)
    # ensure size limit
    while w*h*4 > MAX_BYTES:
        if h > 1:
            h = max(1, h//2)
        elif w > 1:
            w = max(1, w//2)
        else:
            break
    return w, h, single_scan


def _build_rgba(w: int, h: int, rng: random.Random) -> bytes:
    choice = rng.randint(0, 5)
    if choice == 0:
        # solid from palette
        pal = rng.choice(PALETTES)
        return _pattern_solid(w, h, rng.choice(pal))
    if choice == 1:
        # checkerboard
        pal = rng.choice(PALETTES)
        c0, c1 = rng.sample(pal, 2) if len(pal) >= 2 else (pal[0], pal[0])
        tile = rng.choice([1,2,4,8])
        return _pattern_checker(w, h, c0, c1, tile)
    if choice == 2:
        # horizontal gradient with fixed alpha
        alpha = rng.choice([255, 200, 128, 64, 32])
        return _pattern_horizontal_gradient(w, h, alpha)
    if choice == 3:
        # bayer alpha mask over solid color
        base = rng.choice([(255,255,255),(0,0,0),(255,0,0),(0,255,0),(0,0,255),(128,128,128)])
        strength = rng.choice([255,200,160,128,96,64])
        return _pattern_alpha_bayer(w, h, base, strength)
    if choice == 4:
        # stripes horizontal/vertical
        horiz = rng.random() < 0.5
        pal = rng.choice(PALETTES)
        stripe = rng.choice([1,2,3,4,8])
        return _pattern_stripes(w, h, horiz, pal, stripe)
    # mixed random but stable structure: random palette indices
    pal = rng.choice(PALETTES)
    out = bytearray()
    for _y in range(h):
        for _x in range(w):
            r,g,b,a = pal[rng.randrange(len(pal))]
            out += bytes((r,g,b,a))
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    w, h, single = _choose_dims(rng)
    buf = _build_rgba(w, h, rng)
    # Ensure length exactly matches the expected need based on our chosen dims
    need = w * (1 if single else h) * 4
    if len(buf) < need:
        buf = buf + bytes(need - len(buf))
    elif len(buf) > need:
        buf = buf[:need]
    return buf
